def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

exotic_integers = []
k = 1
while len(exotic_integers) < 132:
    n = (2*k - 1)**2
    if count_divisors(n) % 2 == 1:
        exotic_integers.append(n)
    k += 1

print(f"132nd exotic integer: {exotic_integers[131]}")
